(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-087"]={"sura":87,"name_ar":"الأعلى","name_en":"Al-A'la","verses":19,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":19,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=13\" class=\"link\">87:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:13 ஐ பார்க்கவும்"},"13":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>ஸூரத்துல் அஃலாவின் சிறப்புகள்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அலி (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த அத்தியாயத்தை (ஸப்பஹிஸ்ம ரப்பிகல் அஃலா) நேசிப்பவர்களாக இருந்தார்கள்.\"<br />\r\n<br />\r\nஇந்த ஸூரா (அத்தியாயம்) மதீனாவிற்கு ஹிஜ்ரத் செய்வதற்கு முன்னதாக மக்காவில் அருளப்பட்டது. இதற்கு ஆதாரமாக அல்-புகாரி ஒரு செய்தியைப் பதிவு செய்துள்ளார். அல்-பரா இப்னு ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"நபித்தோழர்களில் முதன்முதலாக எங்களிடம் (மதீனாவிற்கு) வந்தவர்கள் முஸ்அப் இப்னு உமைர் (ரழி) மற்றும் இப்னு உம்மி மக்தூம் (ரழி) ஆகியோராவர். அவர்கள் எங்களுக்கு குர்ஆனைக் கற்றுக் கொடுத்தார்கள். பின்னர் அம்மார் (ரழி), பிலால் (ரழி) மற்றும் ஸஃது (ரழி) ஆகியோர் வந்தனர். அதன்பின் உமர் இப்னுல் கத்தாப் (ரழி) அவர்கள் இருபது பேர் கொண்ட குழுவினருடன் வந்தனர். அதன் பின்னரே நபி (ஸல்) அவர்கள் வந்தார்கள். நபி (ஸல்) அவர்களின் வருகையினால் மதீனா மக்கள் அடைந்த மகிழ்ச்சியைப் போல, வேறு எதைக் கண்டும் அவர்கள் அவ்வளவு மகிழ்ச்சி அடைந்ததை நான் பார்த்ததில்லை. சிறுவர்களும் சிறுமியர்களும் கூட, 'இதோ அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வந்துவிட்டார்கள்' என்று கூறும் அளவிற்கு அந்த மகிழ்ச்சி இருந்தது. நபி (ஸல்) அவர்கள் மதீனா வருவதற்கு முன்னரே நான்,<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக.) (<a href=\"qurandisp.php?sura=87&ayah=1\" class=\"link\">87:1</a>) மற்றும் அதைப் போன்ற இதர ஸூராக்களை ஓதி (மனனம் செய்து) வைத்திருந்தேன்.\" மேலும் நபி (ஸல்) அவர்கள் முஆத் (ரழி) அவர்களிடம் பின்வருமாறு கூறியது ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) நூல்களில் உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n«<span class=\"quran-arabic-font text-success\">هَلَّا</span> <span class=\"quran-arabic-font text-success\">صَلَّيْتَ</span> <span class=\"quran-arabic-font text-success\">بِــ</span><br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n<span class=\"quran-arabic-font text-success\">وَالشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">وَضُحَاهَا</span><br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يَغْشَى</span>»<br />\r\n(\"நீர் ஏன் 'மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக', 'சூரியன் மற்றும் அதன் பிரகாசத்தின் மீது சத்தியமாக' மற்றும் 'மூடிக்கொள்ளும் இரவின் மீது சத்தியமாக' ஆகிய அத்தியாயங்களை ஓதித் தொழுகை நடத்தக்கூடாது?\") இமாம் அஹ்மத் அவர்கள் நுஃமான் இப்னு பஷீர் (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரண்டு பெருநாள் தொழுகைகளிலும்,<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أَتَاكَ</span> <span class=\"quran-arabic-font text-success\">حَدِيثُ</span> <span class=\"quran-arabic-font text-success\">الْغَاشِيَةِ</span><br />\r\nஸூரத்துல் அஃலா (அத்தியாயம் 87) மற்றும் ஸூரத்துல் காஷியா (அத்தியாயம் 88) ஆகியவற்றை ஓதுவார்கள். பெருநாள் தொழுகை வெள்ளிக்கிழமையன்று வந்தால், அவ்விரு தொழுகைகளிலும் (பெருநாள் மற்றும் ஜும்ஆ) இவற்றையே ஓதுவார்கள். முஸ்லிம் தனது ஸஹீஹிலும், அபூதாவூத், அத்திர்மிதி, அந்நஸாயீ மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். முஸ்லிம் மற்றும் சுனன் நூலாசிரியர்களின் பதிவில், \"பெருநாட்களிலும் ஜும்ஆவிலும் நபி (ஸல்) அவர்கள் இவ்விரு அத்தியாயங்களை ஓதுவார்கள்; அவை ஒரே நாளில் வந்தாலும் இரண்டிலும் இவற்றையே ஓதுவார்கள்\" எனக் கூறப்பட்டுள்ளது. இமாம் அஹ்மத் தனது முஸ்னதில் உபை இப்னு கஃப் (ரழி), அப்துல்லாஹ் இப்னு அப்பாஸ் (ரழி), அப்துர் ரஹ்மான் இப்னு அப்ஸா (ரழி) மற்றும் முஃமின்களின் அன்னை ஆயிஷா (ரழி) ஆகியோர் வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் (வித்ரு தொழுகையில்),<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُونَ</span><br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span><br />\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக), (கூறுவீராக: 'நிராகரிப்பாளர்களே!') மற்றும் (கூறுவீராக: 'அவன் அல்லாஹ் ஒருவன்') ஆகியவற்றை ஓதுவார்கள். ஆயிஷா (ரழி) அவர்கள் தனது அறிவிப்பில், நபி (ஸல்) அவர்கள் முஅவ்வித்ததைன் (அல்-ஃபலக் மற்றும் அந்-நாஸ்) அத்தியாயங்களையும் ஓதுவார்கள் எனக் கூடுதலாகக் குறிப்பிட்டுள்ளார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>தஸ்பீஹ் செய்யுமாறு கட்டளையும் அதற்கான பதிலும்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் இப்னு அப்பாஸ் (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக) என்று ஓதும் போதெல்லாம்,<br />\r\n«<span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">رَبِّيَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span>»<br />\r\n(மிக உயர்ந்தவனான என் இறைவன் தூயவன்) எனக் கூறுவார்கள். இப்னு ஜரீர் அவர்கள் இப்னு இஸ்ஹாக் அல்-ஹம்தானி வழியாகப் பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள்<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\nஎன்று ஓதும் போது, \"மிக உயர்ந்தவனான என் இறைவன் தூயவன்\" எனக் கூறுவார்கள். மேலும்,<br />\r\n<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أُقْسِمُ</span> <span class=\"quran-arabic-font text-success\">بِيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span><br />\r\n(மறுமை நாளின் மீது நான் சத்தியம் செய்கிறேன்) (<a href=\"qurandisp.php?sura=75&ayah=1\" class=\"link\">75:1</a>) என்ற அத்தியாயத்தை ஓதி, அதன் முடிவில் உள்ள<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِقَادِرٍ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُحْيِيَ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَى</span><br />\r\n(இறந்தோரை உயிர்ப்பிக்க அவன் ஆற்றல் பெற்றவன் அல்லவா?) (<a href=\"qurandisp.php?sura=75&ayah=40\" class=\"link\">75:40</a>) என்ற வசனத்தை அடையும்போது, \"நிச்சயமாக, நீ தூயவன்\" எனக் கூறுவார்கள். கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் நபி (ஸல்) அவர்கள்,<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span><br />\r\nஎன்பதை ஓதும்போது,<br />\r\n«<span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">رَبِّيَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span>»<br />\r\n(மிக உயர்ந்தவனான என் இறைவன் தூயவன்) எனக் கூறுவார்கள் என்று எங்களுக்குச் சொல்லப்பட்டுள்ளது.\"<br />\r\n<br />\r\n<strong>படைத்தல், நிர்ணயித்தல் மற்றும் தாவரங்களை வெளிப்படுத்துதல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">فَسَوَّى</span><br />\r\n(அவனே படைத்துச் சீராக்கினான்.) அதாவது, அவன் படைப்பினங்களைப் படைத்து, ஒவ்வொரு படைப்பையும் மிகச் சிறந்த வடிவத்தில் உருவாக்கினான். பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فَهَدَى</span><br />\r\n(அவனே (அனைத்தையும்) நிர்ணயித்து வழிகாட்டினான்.) முஜாஹித் (ரழி) கூறினார்கள்: \"அவன் மனிதனுக்குத் துன்பம் மற்றும் இன்பத்திற்கான வழியைக் காட்டினான்; கால்நடைகளுக்கு அவற்றின் மேய்ச்சல் நிலங்களுக்கு வழிகாட்டினான்.\" ஃபிர்அவ்னிடம் மூஸா (அலை) கூறியதாக அல்லாஹ் குறிப்பிடும் பின்வரும் வசனத்தைப் போன்றதே இதுவும்:<br />\r\n<span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَعْطَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">هَدَى</span><br />\r\n(\"எங்கள் இறைவன் எத்தகையவன் என்றால், அவன் ஒவ்வொரு பொருளுக்கும் அதன் உருவத்தை (இயல்பை) வழங்கி, பின்னர் அதற்கு வழிகாட்டினான்.\") (<a href=\"qurandisp.php?sura=20&ayah=50\" class=\"link\">20:50</a>). அதாவது, அவன் ஒரு குறிப்பிட்ட அளவை நிர்ணயித்து, படைப்பினங்களை அதன்பால் வழிநடத்தினான். ஸஹீஹ் முஸ்லிமில் அப்துல்லாஹ் இப்னு அம்ர் (ரழி) வாயிலாகப் பதிவாகியுள்ள ஹதீஸும் இதனை உறுதிப்படுத்துகிறது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">مَقَادِيرَ</span> <span class=\"quran-arabic-font text-success\">الْخَلَائِقِ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِخَمْسِينَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">سَنَةٍ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">عَرْشُهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمَاءِ</span>»<br />\r\n(நிச்சயமாக அல்லாஹ், வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே படைப்பினங்களின் விதியை நிர்ணயித்துவிட்டான்; அப்போது அவனது அர்ஷ் (சிம்மாசனம்) நீரின் மேல் இருந்தது.) அல்லாஹ்வின் வசனமான,<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">الْمَرْعَى</span><br />\r\n(அவனே மேய்ச்சல் புற்களை வெளிப்படுத்தினான்,) என்பது அனைத்து வகையான தாவரங்களையும் பயிர்களையும் குறிக்கிறது.<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلَهُ</span> <span class=\"quran-arabic-font text-success\">غُثَاءً</span> <span class=\"quran-arabic-font text-success\">أَحْوَى</span><br />\r\n(பின்னர் அதனை காய்ந்த கருகிய சருகாக ஆக்கினான்.) இப்னு அப்பாஸ் (ரழி) கூறினார்கள்: \"உலர்ந்து போனது மற்றும் நிறம் மாறியது.\" முஜாஹித், கதாதா மற்றும் இப்னு ஸைத் ஆகியோரும் இவ்வாறே கூறியுள்ளனர்.<br />\r\n<br />\r\n<strong>நபி (ஸல்) அவர்கள் வஹீ (இறைச்செய்தி)யை மறப்பதில்லை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">سَنُقْرِئُكَ</span><br />\r\n(நாம் உமக்கு ஓதக் கற்றுத் தருவோம்,) அதாவது, 'ஓ முஹம்மதே!'<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَنْسَى</span><br />\r\n(நீர் மறக்கமாட்டீர்,) இது நபி (ஸல்) அவர்களுக்கு அல்லாஹ் அளிக்கும் வாக்குறுதியாகும்; அவர் மறக்காத வகையில் ஓதக் கற்றுத் தருவதாக அல்லாஹ் அறிவிக்கிறான்.<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n(அல்லாஹ் நாடினாலன்றி.) கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ் நாடியதைத் தவிர எதையும் நபி (ஸல்) அவர்கள் மறந்ததில்லை.\"<br />\r\n<span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَنْسَى</span><br />\r\nஎன்ற வசனத்திற்கு \"நீர் மறக்காதீர்\" என்றும் பொருள் கூறப்பட்டுள்ளது. அதாவது, \"நாம் உமக்கு ஓதக் கற்றுத் தருவதை நீர் மறக்காதீர்; ஆனால் அல்லாஹ் நாடினால் (சில வசனங்களை) நீக்கிவிடுவான், அவ்வாறு நீக்கப்பட்டவற்றை நீர் விட்டுவிடுவதில் உம்மீது குற்றமில்லை\" என்பதாகும். அல்லாஹ்வின் வசனமான:<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">الْجَهْرَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَخْفَى</span><br />\r\n(நிச்சயமாக அவன் வெளிப்படையானதையும் மறைவானதையும் அறிகிறான்.) அதாவது, படைப்பினங்கள் பகிரங்கமாகச் செய்வதையும், மறைத்துச் செய்யும் சொல் மற்றும் செயல்களையும் அவன் அறிகிறான். அவனுக்கு எதுவுமே மறைவானதல்ல. பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">وَنُيَسِّرُكَ</span> <span class=\"quran-arabic-font text-success\">لِلْيُسْرَى</span><br />\r\n(மேலும், நாம் உமக்கு எளிதான வழியை மென்மேலும் எளிதாக்குவோம்.) அதாவது, 'நற்செயல்களையும் நற்பண்புகளையும் உமக்கு எளிதாக்குவோம். கோணல்கள், சிரமங்கள் அல்லது கஷ்டங்கள் ஏதுமில்லாத, மிகவும் எளிமையான, சகிப்புத்தன்மை வாய்ந்த, நேர்மையான மார்க்கச் சட்டங்களை உமக்காக வழங்குவோம்.'<br />\r\n<br />\r\n<strong>நினைவூட்டுமாறு கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">فَذَكِّرْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">نَفَعَتِ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرَى</span><br />\r\n(ஆகவே, நினைவூட்டல் பயனளிக்கும் எனில் நீர் நினைவூட்டுவீராக.) அதாவது, நினைவூட்டுதல் பலன் தரும் இடங்களில் நினைவூட்டுங்கள். இதிலிருந்து அறிவைப் பரப்புவதற்கான ஒரு ஒழுக்கத்தை நாம் அறிகிறோம்; அதாவது, தகுதியற்றவர்களிடம் அல்லது பயனடையாதவர்களிடம் அறிவை வீணாக்கக்கூடாது. முஃமின்களின் தலைவர் அலீ (ரழி) அவர்கள் கூறினார்கள்: \"மக்களின் புத்திக்கு எட்டாத எதையும் நீங்கள் அவர்களிடம் கூறாதீர்கள்; ஏனெனில் அது அவர்களில் சிலருக்கு ஒரு ஃபித்னாவாக (சோதனையாக) அமைந்துவிடும்.\" மேலும் அவர்கள், \"மக்கள் அறிந்தவற்றை மட்டும் அவர்களிடம் பேசுங்கள். அல்லாஹ்வும் அவனது தூதரும் பொய்யாக்கப்படுவதை நீங்கள் விரும்புவீர்களா?\" என்றும் கூறினார்கள். அல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">سَيَذَّكَّرُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span><br />\r\n(அஞ்சுபவன் நல்லுபதேசத்தைப் பெறுவான்,) அதாவது, 'ஓ முஹம்மதே! எவருடைய இதயம் அல்லாஹ்வை அஞ்சுகிறதோ மற்றும் தான் அவனைச் சந்திக்கப் போவதை உணர்கிறாரோ, அவர் நீர் அளிக்கும் நினைவூட்டலை ஏற்றுக்கொள்வார்.'<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَتَجَنَّبُهَا</span> <span class=\"quran-arabic-font text-success\">الْأَشْقَى</span> - <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">يَصْلَى</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">الْكُبْرَى</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَحْيَا</span><br />\r\n(துர்ப்பாக்கியசாலி அதனைத் தவிர்ப்பான். அவன் மகா நெருப்பில் நுழைவான். அங்கு அவன் சாகவும் மாட்டான், வாழவும் மாட்டான்.) அதாவது, அவன் இறந்து ஓய்வுபெறவும் மாட்டான், பயனுள்ள வாழ்வை வாழவும் மாட்டான். மாறாக, அவனது வாழ்க்கை அவனுக்குத் தீங்காகவே அமையும்; ஏனெனில் அவன் அனுபவிக்கும் கடுமையான வேதனைகளையும் பல்வேறு தண்டனைகளையும் உணர்வதற்காகவே அவன் அங்கு இருப்பான். இமாம் அஹ்மத் அவர்கள் அபூ ஸயீத் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلُهَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمُوتُونَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَحْيَوْنَ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">أُنَاسٌ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">بِهِمُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَةَ</span> <span class=\"quran-arabic-font text-success\">فَيُمِيتُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْخُلُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الشُّفَعَاءُ</span> <span class=\"quran-arabic-font text-success\">فَيَأْخُذُ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلُ</span> <span class=\"quran-arabic-font text-success\">الضِّبَارَةَ</span> <span class=\"quran-arabic-font text-success\">فَيُنْبِتُهُمْ</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">يَنْبُتُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">نَهْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَيَا،</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">الْحَيَاةِ،</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">الْحَيَوَانِ</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">نَهْرِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَيَنْبُتُونَ</span> <span class=\"quran-arabic-font text-success\">نَبَاتَ</span> <span class=\"quran-arabic-font text-success\">الْحِبَّةِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَمِيلِ</span> <span class=\"quran-arabic-font text-success\">السَّيْلِ</span>»<br />\r\n(\"நரகத்திற்குத் தகுதியான நரகவாசிகளைப் பொறுத்தவரை, அவர்கள் அங்கு சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். ஆனால் அல்லாஹ் யாருக்குக் கருணை காட்ட நாடுகிறானோ, அவர்களை நரக நெருப்பில் மரணிக்கச் செய்வான். பின்னர் பரிந்துரையாளர்கள் (ஷஃபாஅத் செய்ய) அனுமதிக்கப்படுவார்கள். ஒரு மனிதர் தனது குழுவினரை அழைத்துச் சென்று அல்-ஹயா (அல்லது அல்-ஹயாத் அல்லது அல்-ஹயவான் அல்லது சுவர்க்கத்தின் ஆறு) என்று அழைக்கப்படும் நதியில் அவர்களை நடுவார் (அல்லது அவர்கள் அங்கு முளைப்பார்கள்). ஓடும் நீரோடையின் ஓரத்தில் உள்ள வண்டல் மண்ணில் ஒரு விதை முளைப்பதைப் போல அவர்கள் மீண்டும் உயிர் பெற்று முளைப்பார்கள்.\") பின்னர் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَا</span> <span class=\"quran-arabic-font text-success\">تَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الشَّجَرَةَ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">خَضْرَاءَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">صَفْرَاءَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">خَضْرَاءَ؟</span>»<br />\r\n(\"மரம் பச்சையாக இருந்து, பின்னர் மஞ்சளாக மாறி, மீண்டும் பச்சையாவதை நீங்கள் பார்த்ததில்லையா?\") அப்போது அங்கிருந்தவர்களில் சிலர், \"நபி (ஸல்) அவர்கள் பாலைவனவாசியைப் போல (இயற்கை உதாரணங்களைக் கூறி) பேசுகிறார்கள்\" என்று கூறினார்கள். இமாம் அஹ்மத் அவர்கள் அபூ ஸயீத் (ரழி) வாயிலாக மற்றுமொரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">أَهْلُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلُهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَمُوتُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَحْيَوْنَ،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنْ</span> <span class=\"quran-arabic-font text-success\">أُنَاسٌ</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">كما</span> <span class=\"quran-arabic-font text-success\">قال</span> <span class=\"quran-arabic-font text-success\">تُصِيبُهُمُ</span> <span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">أو</span> <span class=\"quran-arabic-font text-success\">قال</span>: <span class=\"quran-arabic-font text-success\">بِخَطَايَاهُمْ</span> <span class=\"quran-arabic-font text-success\">فَيُمِيتُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِمَاتَةً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">صَارُوا</span> <span class=\"quran-arabic-font text-success\">فَحْمًا</span> <span class=\"quran-arabic-font text-success\">أُذِنَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الشَّفَاعَةِ،</span> <span class=\"quran-arabic-font text-success\">فَجِيءَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">ضَبَائِرَ</span> <span class=\"quran-arabic-font text-success\">ضَبَائِرَ</span> <span class=\"quran-arabic-font text-success\">فَبُثُّوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْهَارِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَفِيضُوا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ،</span> <span class=\"quran-arabic-font text-success\">فَيَنْبُتُونَ</span> <span class=\"quran-arabic-font text-success\">نَبَاتَ</span> <span class=\"quran-arabic-font text-success\">الْحِبَّةِ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حَمِيلِ</span> <span class=\"quran-arabic-font text-success\">السَّيْلِ</span>»<br />\r\n(\"நரகத்தில் நிரந்தரமாகத் தங்கும் நரகவாசிகள் அங்கு சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். ஆனால், ஒரு கூட்டத்தினர் தங்களது பாவங்களின் காரணமாக நரக நெருப்பால் தண்டிக்கப்பட்டு, கரிக்கட்டையாக மாறும் வரை மரணிக்கச் செய்யப்படுவார்கள். பின்னர் அவர்களுக்குப் பரிந்துரை செய்ய அனுமதி வழங்கப்படும்; அவர்கள் குழு குழுவாகக் கொண்டு வரப்பட்டு சுவர்க்கத்தின் ஆறுகளில் விடப்படுவார்கள். அப்போது, 'சுவர்க்கவாசிகளே! இவர்கள் மீது தண்ணீரை ஊற்றுங்கள்' என்று கூறப்படும். வெள்ளத்தின் ஓரத்தில் உள்ள வண்டல் மண்ணில் விதை முளைப்பதைப் போல அவர்கள் மீண்டும் உயிர் பெறுவார்கள்.\") அப்போது அங்கிருந்தவர்களில் ஒருவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாலைவனப் பகுதியில் வாழ்ந்தவரைப் போலவே (உவமைகளைக் கூறிப்) பேசுகிறார்கள்\" என்றார். இந்த ஹதீஸை முஸ்லிமும் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\n<strong>தொழுகையும், தூய்மைப்படுத்துதலும்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span><br />\r\n(நிச்சயமாக எவர் தூய்மை அடைந்து, தனது இறைவனின் பெயரை நினைவுகூர்ந்து தொழுதாரோ அவர் வெற்றி பெற்றுவிட்டார்.) அதாவது, எவர் தனது ஆத்மாவைத் தூய்மைப்படுத்தி, அருவருக்கத்தக்க பண்புகளை விட்டும் அதனைச் சுத்தப்படுத்தினாரோ, பின்னர் தனக்குக் கடமையாக்கப்பட்ட நேரத்தில் தொழுகையை நிறைவேற்றினாரோ அவர் வெற்றி பெற்றுவிட்டார். உமர் இப்னு அப்துல் அஸீஸ் (ரஹ்) அவர்கள், மக்கள் நோன்புப் பெருநாள் தொழுகைக்குச் செல்லும் போது இந்த வசனத்தை ஓதுமாறும், ஸதக்கத்துல் ஃபித்ர் (நோன்புப் பெருநாள் தர்மம்) வழங்குமாறும் கட்டளையிடுவார்கள்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">تُؤْثِرُونَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> - <span class=\"quran-arabic-font text-success\">وَالْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى</span><br />\r\n(எனினும், நீங்கள் உலக வாழ்க்கையையே தேர்ந்தெடுக்கிறீர்கள். ஆனால் மறுமையோ சிறந்ததும் நிலையானதும் ஆகும்.) அதாவது, நீங்கள் உலகத்தின் மீதுள்ள அன்பினால், மறுமையை விட உலகத்திற்கே முன்னுரிமை அளிக்கிறீர்கள். ஆனால் உலகத்தை விட மறுமையே சிறந்தது; அதுவே நிலையானது. இமாம் அஹ்மத் அவர்கள் அபூ மூஸா அல்-அஷ்அரீ (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: \"யார் தனது உலகத்தை நேசிக்கிறாரோ அவர் தனது மறுமைக்குப் பாதிப்பை ஏற்படுத்துகிறார். யார் தனது மறுமையை நேசிக்கிறாரோ அவர் தனது உலகத்திற்குப் பாதிப்பை ஏற்படுத்துகிறார். எனவே, அழிந்து போவதை விட நிலைத்திருப்பதற்கே முன்னுரிமை கொடுங்கள்.\"<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">الصُّحُفِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> - <span class=\"quran-arabic-font text-success\">صُحُفِ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">وَمُوسَى</span><br />\r\n(நிச்சயமாக இது முந்தைய வேதங்களிலும் உள்ளது; (அதாவது) இப்ராஹீம், மூஸா ஆகியோரின் ஏடுகளிலும் உள்ளது.) அதாவது, முந்தைய வசனங்களில் கூறப்பட்ட நற்போதனைகள், இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) ஆகியோரின் ஏடுகளிலும் உறுதிப்படுத்தப்பட்டுள்ளன. அபூதர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"நான், 'அல்லாஹ்வின் தூதரே! இப்ராஹீம் (அலை) அவர்களின் ஏடுகளில் என்ன இருந்தது?' என்று கேட்டேன். அதற்கு நபி (ஸல்) அவர்கள், 'அவை அனைத்தும் முன்னுதாரணங்களாக இருந்தன' என்று கூறிவிட்டுச் சிலவற்றை விவரித்தார்கள்: \"ஆதிக்கமும் சோதனையும் வழங்கப்பட்ட மன்னரே! உலகைச் சேகரிப்பதற்காக நான் உம்மை அனுப்பவில்லை. மாறாக, அநீதி இழைக்கப்பட்டவனின் பிரார்த்தனைக்கும் எனக்குமிடையே தடையை ஏற்படுத்துவதைத் தடுப்பதற்காகவே உம்மை அனுப்பினேன்; (அநீதி இழைக்கப்பட்டவன்) காஃபிராக இருந்தாலும் அவனது பிரார்த்தனையை நான் தட்டமாட்டேன்.\" பிறகு நான், 'மூஸா (அலை) அவர்களின் ஏடுகளில் என்ன இருந்தது?' என்று கேட்டேன். அதற்கு அவர்கள், 'அவை அனைத்தும் படிப்பினைகளாக இருந்தன' என்று கூறினார்கள்: \"மரணத்தை உறுதியாக அறிந்திருந்தும் மகிழ்ச்சியாக இருப்பவனைப் பற்றி நான் வியப்படைகிறேன்; நரகத்தை உறுதியாக அறிந்திருந்தும் சிரிப்பவனைப் பற்றி நான் வியப்படைகிறேன்; உலகத்தையும் அது தனது உரிமையாளர்களை மாற்றிக்கொண்டே இருப்பதையும் கண்டும், அதில் அமைதி காண்பவனைப் பற்றி நான் வியப்படைகிறேன்; விதியை நம்பியும் (இழப்பைக் கண்டு) சோகத்தில் ஆழ்ந்துவிடுபவனைப் பற்றி நான் வியப்படைகிறேன்; மறுமை விசாரணையை நம்பியும் அமல் செய்யாமல் இருப்பவனைப் பற்றி நான் வியப்படைகிறேன்.\"\" (நஸயீ)<br />\r\n(தப்ஸீர் இப்னு கஸீர் சுருக்கம் முற்றிற்று.)<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nஸூரத்துல் அஃலாவின் சிறப்புகள்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அலி (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த அத்தியாயத்தை (ஸப்பஹிஸ்ம ரப்பிகல் அஃலா) நேசிப்பவர்களாக இருந்தார்கள்.\"\n\r\n\n\r\nஇந்த ஸூரா (அத்தியாயம்) மதீனாவிற்கு ஹிஜ்ரத் செய்வதற்கு முன்னதாக மக்காவில் அருளப்பட்டது. இதற்கு ஆதாரமாக அல்-புகாரி ஒரு செய்தியைப் பதிவு செய்துள்ளார். அல்-பரா இப்னு ஆஸிப் (ரழி) அவர்கள் கூறினார்கள்: \"நபித்தோழர்களில் முதன்முதலாக எங்களிடம் (மதீனாவிற்கு) வந்தவர்கள் முஸ்அப் இப்னு உமைர் (ரழி) மற்றும் இப்னு உம்மி மக்தூம் (ரழி) ஆகியோராவர். அவர்கள் எங்களுக்கு குர்ஆனைக் கற்றுக் கொடுத்தார்கள். பின்னர் அம்மார் (ரழி), பிலால் (ரழி) மற்றும் ஸஃது (ரழி) ஆகியோர் வந்தனர். அதன்பின் உமர் இப்னுல் கத்தாப் (ரழி) அவர்கள் இருபது பேர் கொண்ட குழுவினருடன் வந்தனர். அதன் பின்னரே நபி (ஸல்) அவர்கள் வந்தார்கள். நபி (ஸல்) அவர்களின் வருகையினால் மதீனா மக்கள் அடைந்த மகிழ்ச்சியைப் போல, வேறு எதைக் கண்டும் அவர்கள் அவ்வளவு மகிழ்ச்சி அடைந்ததை நான் பார்த்ததில்லை. சிறுவர்களும் சிறுமியர்களும் கூட, 'இதோ அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் வந்துவிட்டார்கள்' என்று கூறும் அளவிற்கு அந்த மகிழ்ச்சி இருந்தது. நபி (ஸல்) அவர்கள் மதீனா வருவதற்கு முன்னரே நான்,\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக.) (87:1) மற்றும் அதைப் போன்ற இதர ஸூராக்களை ஓதி (மனனம் செய்து) வைத்திருந்தேன்.\" மேலும் நபி (ஸல்) அவர்கள் முஆத் (ரழி) அவர்களிடம் பின்வருமாறு கூறியது ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) நூல்களில் உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n«هَلَّا صَلَّيْتَ بِــ\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\nوَالشَّمْسِ وَضُحَاهَا\n\r\nوَاللَّيْلِ إِذَا يَغْشَى»\n\r\n(\"நீர் ஏன் 'மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக', 'சூரியன் மற்றும் அதன் பிரகாசத்தின் மீது சத்தியமாக' மற்றும் 'மூடிக்கொள்ளும் இரவின் மீது சத்தியமாக' ஆகிய அத்தியாயங்களை ஓதித் தொழுகை நடத்தக்கூடாது?\") இமாம் அஹ்மத் அவர்கள் நுஃமான் இப்னு பஷீர் (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரண்டு பெருநாள் தொழுகைகளிலும்,\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\nهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ\n\r\nஸூரத்துல் அஃலா (அத்தியாயம் 87) மற்றும் ஸூரத்துல் காஷியா (அத்தியாயம் 88) ஆகியவற்றை ஓதுவார்கள். பெருநாள் தொழுகை வெள்ளிக்கிழமையன்று வந்தால், அவ்விரு தொழுகைகளிலும் (பெருநாள் மற்றும் ஜும்ஆ) இவற்றையே ஓதுவார்கள். முஸ்லிம் தனது ஸஹீஹிலும், அபூதாவூத், அத்திர்மிதி, அந்நஸாயீ மற்றும் இப்னு மாஜா ஆகியோரும் இதனைப் பதிவு செய்துள்ளனர். முஸ்லிம் மற்றும் சுனன் நூலாசிரியர்களின் பதிவில், \"பெருநாட்களிலும் ஜும்ஆவிலும் நபி (ஸல்) அவர்கள் இவ்விரு அத்தியாயங்களை ஓதுவார்கள்; அவை ஒரே நாளில் வந்தாலும் இரண்டிலும் இவற்றையே ஓதுவார்கள்\" எனக் கூறப்பட்டுள்ளது. இமாம் அஹ்மத் தனது முஸ்னதில் உபை இப்னு கஃப் (ரழி), அப்துல்லாஹ் இப்னு அப்பாஸ் (ரழி), அப்துர் ரஹ்மான் இப்னு அப்ஸா (ரழி) மற்றும் முஃமின்களின் அன்னை ஆயிஷா (ரழி) ஆகியோர் வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் (வித்ரு தொழுகையில்),\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\nقُلْ يَا أَيُّهَا الْكَافِرُونَ\n\r\nقُلْ هُوَ اللَّهُ أَحَدٌ\n\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக), (கூறுவீராக: 'நிராகரிப்பாளர்களே!') மற்றும் (கூறுவீராக: 'அவன் அல்லாஹ் ஒருவன்') ஆகியவற்றை ஓதுவார்கள். ஆயிஷா (ரழி) அவர்கள் தனது அறிவிப்பில், நபி (ஸல்) அவர்கள் முஅவ்வித்ததைன் (அல்-ஃபலக் மற்றும் அந்-நாஸ்) அத்தியாயங்களையும் ஓதுவார்கள் எனக் கூடுதலாகக் குறிப்பிட்டுள்ளார்கள்.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nதஸ்பீஹ் செய்யுமாறு கட்டளையும் அதற்கான பதிலும்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் இப்னு அப்பாஸ் (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\n(மிக உயர்ந்த உமது இறைவனின் திருநாமத்தைத் துதிப்பீராக) என்று ஓதும் போதெல்லாம்,\n\r\n«سُبْحَانَ رَبِّيَ الْأَعْلَى»\n\r\n(மிக உயர்ந்தவனான என் இறைவன் தூயவன்) எனக் கூறுவார்கள். இப்னு ஜரீர் அவர்கள் இப்னு இஸ்ஹாக் அல்-ஹம்தானி வழியாகப் பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள்\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\nஎன்று ஓதும் போது, \"மிக உயர்ந்தவனான என் இறைவன் தூயவன்\" எனக் கூறுவார்கள். மேலும்,\n\r\nلَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ\n\r\n(மறுமை நாளின் மீது நான் சத்தியம் செய்கிறேன்) (75:1) என்ற அத்தியாயத்தை ஓதி, அதன் முடிவில் உள்ள\n\r\nأَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى\n\r\n(இறந்தோரை உயிர்ப்பிக்க அவன் ஆற்றல் பெற்றவன் அல்லவா?) (75:40) என்ற வசனத்தை அடையும்போது, \"நிச்சயமாக, நீ தூயவன்\" எனக் கூறுவார்கள். கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ்வின் நபி (ஸல்) அவர்கள்,\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى\n\r\nஎன்பதை ஓதும்போது,\n\r\n«سُبْحَانَ رَبِّيَ الْأَعْلَى»\n\r\n(மிக உயர்ந்தவனான என் இறைவன் தூயவன்) எனக் கூறுவார்கள் என்று எங்களுக்குச் சொல்லப்பட்டுள்ளது.\"\n\r\n\n\r\nபடைத்தல், நிர்ணயித்தல் மற்றும் தாவரங்களை வெளிப்படுத்துதல்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nالَّذِي خَلَقَ فَسَوَّى\n\r\n(அவனே படைத்துச் சீராக்கினான்.) அதாவது, அவன் படைப்பினங்களைப் படைத்து, ஒவ்வொரு படைப்பையும் மிகச் சிறந்த வடிவத்தில் உருவாக்கினான். பிறகு அல்லாஹ் கூறுகிறான்:\n\r\nوَالَّذِي قَدَّرَ فَهَدَى\n\r\n(அவனே (அனைத்தையும்) நிர்ணயித்து வழிகாட்டினான்.) முஜாஹித் (ரழி) கூறினார்கள்: \"அவன் மனிதனுக்குத் துன்பம் மற்றும் இன்பத்திற்கான வழியைக் காட்டினான்; கால்நடைகளுக்கு அவற்றின் மேய்ச்சல் நிலங்களுக்கு வழிகாட்டினான்.\" ஃபிர்அவ்னிடம் மூஸா (அலை) கூறியதாக அல்லாஹ் குறிப்பிடும் பின்வரும் வசனத்தைப் போன்றதே இதுவும்:\n\r\nرَبُّنَا الَّذِي أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى\n\r\n(\"எங்கள் இறைவன் எத்தகையவன் என்றால், அவன் ஒவ்வொரு பொருளுக்கும் அதன் உருவத்தை (இயல்பை) வழங்கி, பின்னர் அதற்கு வழிகாட்டினான்.\") (20:50). அதாவது, அவன் ஒரு குறிப்பிட்ட அளவை நிர்ணயித்து, படைப்பினங்களை அதன்பால் வழிநடத்தினான். ஸஹீஹ் முஸ்லிமில் அப்துல்லாஹ் இப்னு அம்ர் (ரழி) வாயிலாகப் பதிவாகியுள்ள ஹதீஸும் இதனை உறுதிப்படுத்துகிறது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«إِنَّ اللهَ قَدَّرَ مَقَادِيرَ الْخَلَائِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَاوَاتِ وَالْأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ»\n\r\n(நிச்சயமாக அல்லாஹ், வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே படைப்பினங்களின் விதியை நிர்ணயித்துவிட்டான்; அப்போது அவனது அர்ஷ் (சிம்மாசனம்) நீரின் மேல் இருந்தது.) அல்லாஹ்வின் வசனமான,\n\r\nوَالَّذِي أَخْرَجَ الْمَرْعَى\n\r\n(அவனே மேய்ச்சல் புற்களை வெளிப்படுத்தினான்,) என்பது அனைத்து வகையான தாவரங்களையும் பயிர்களையும் குறிக்கிறது.\n\r\nفَجَعَلَهُ غُثَاءً أَحْوَى\n\r\n(பின்னர் அதனை காய்ந்த கருகிய சருகாக ஆக்கினான்.) இப்னு அப்பாஸ் (ரழி) கூறினார்கள்: \"உலர்ந்து போனது மற்றும் நிறம் மாறியது.\" முஜாஹித், கதாதா மற்றும் இப்னு ஸைத் ஆகியோரும் இவ்வாறே கூறியுள்ளனர்.\n\r\n\n\r\nநபி (ஸல்) அவர்கள் வஹீ (இறைச்செய்தி)யை மறப்பதில்லை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nسَنُقْرِئُكَ\n\r\n(நாம் உமக்கு ஓதக் கற்றுத் தருவோம்,) அதாவது, 'ஓ முஹம்மதே!'\n\r\nفَلَا تَنْسَى\n\r\n(நீர் மறக்கமாட்டீர்,) இது நபி (ஸல்) அவர்களுக்கு அல்லாஹ் அளிக்கும் வாக்குறுதியாகும்; அவர் மறக்காத வகையில் ஓதக் கற்றுத் தருவதாக அல்லாஹ் அறிவிக்கிறான்.\n\r\nإِلَّا مَا شَاءَ اللَّهُ\n\r\n(அல்லாஹ் நாடினாலன்றி.) கதாதா (ரழி) கூறினார்கள்: \"அல்லாஹ் நாடியதைத் தவிர எதையும் நபி (ஸல்) அவர்கள் மறந்ததில்லை.\"\n\r\nفَلَا تَنْسَى\n\r\nஎன்ற வசனத்திற்கு \"நீர் மறக்காதீர்\" என்றும் பொருள் கூறப்பட்டுள்ளது. அதாவது, \"நாம் உமக்கு ஓதக் கற்றுத் தருவதை நீர் மறக்காதீர்; ஆனால் அல்லாஹ் நாடினால் (சில வசனங்களை) நீக்கிவிடுவான், அவ்வாறு நீக்கப்பட்டவற்றை நீர் விட்டுவிடுவதில் உம்மீது குற்றமில்லை\" என்பதாகும். அல்லாஹ்வின் வசனமான:\n\r\nإِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَى\n\r\n(நிச்சயமாக அவன் வெளிப்படையானதையும் மறைவானதையும் அறிகிறான்.) அதாவது, படைப்பினங்கள் பகிரங்கமாகச் செய்வதையும், மறைத்துச் செய்யும் சொல் மற்றும் செயல்களையும் அவன் அறிகிறான். அவனுக்கு எதுவுமே மறைவானதல்ல. பிறகு அல்லாஹ் கூறுகிறான்:\n\r\nوَنُيَسِّرُكَ لِلْيُسْرَى\n\r\n(மேலும், நாம் உமக்கு எளிதான வழியை மென்மேலும் எளிதாக்குவோம்.) அதாவது, 'நற்செயல்களையும் நற்பண்புகளையும் உமக்கு எளிதாக்குவோம். கோணல்கள், சிரமங்கள் அல்லது கஷ்டங்கள் ஏதுமில்லாத, மிகவும் எளிமையான, சகிப்புத்தன்மை வாய்ந்த, நேர்மையான மார்க்கச் சட்டங்களை உமக்காக வழங்குவோம்.'\n\r\n\n\r\nநினைவூட்டுமாறு கட்டளை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nفَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى\n\r\n(ஆகவே, நினைவூட்டல் பயனளிக்கும் எனில் நீர் நினைவூட்டுவீராக.) அதாவது, நினைவூட்டுதல் பலன் தரும் இடங்களில் நினைவூட்டுங்கள். இதிலிருந்து அறிவைப் பரப்புவதற்கான ஒரு ஒழுக்கத்தை நாம் அறிகிறோம்; அதாவது, தகுதியற்றவர்களிடம் அல்லது பயனடையாதவர்களிடம் அறிவை வீணாக்கக்கூடாது. முஃமின்களின் தலைவர் அலீ (ரழி) அவர்கள் கூறினார்கள்: \"மக்களின் புத்திக்கு எட்டாத எதையும் நீங்கள் அவர்களிடம் கூறாதீர்கள்; ஏனெனில் அது அவர்களில் சிலருக்கு ஒரு ஃபித்னாவாக (சோதனையாக) அமைந்துவிடும்.\" மேலும் அவர்கள், \"மக்கள் அறிந்தவற்றை மட்டும் அவர்களிடம் பேசுங்கள். அல்லாஹ்வும் அவனது தூதரும் பொய்யாக்கப்படுவதை நீங்கள் விரும்புவீர்களா?\" என்றும் கூறினார்கள். அல்லாஹ் கூறினான்:\n\r\nسَيَذَّكَّرُ مَنْ يَخْشَى\n\r\n(அஞ்சுபவன் நல்லுபதேசத்தைப் பெறுவான்,) அதாவது, 'ஓ முஹம்மதே! எவருடைய இதயம் அல்லாஹ்வை அஞ்சுகிறதோ மற்றும் தான் அவனைச் சந்திக்கப் போவதை உணர்கிறாரோ, அவர் நீர் அளிக்கும் நினைவூட்டலை ஏற்றுக்கொள்வார்.'\n\r\nوَيَتَجَنَّبُهَا الْأَشْقَى - الَّذِي يَصْلَى النَّارَ الْكُبْرَى - ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَا\n\r\n(துர்ப்பாக்கியசாலி அதனைத் தவிர்ப்பான். அவன் மகா நெருப்பில் நுழைவான். அங்கு அவன் சாகவும் மாட்டான், வாழவும் மாட்டான்.) அதாவது, அவன் இறந்து ஓய்வுபெறவும் மாட்டான், பயனுள்ள வாழ்வை வாழவும் மாட்டான். மாறாக, அவனது வாழ்க்கை அவனுக்குத் தீங்காகவே அமையும்; ஏனெனில் அவன் அனுபவிக்கும் கடுமையான வேதனைகளையும் பல்வேறு தண்டனைகளையும் உணர்வதற்காகவே அவன் அங்கு இருப்பான். இமாம் அஹ்மத் அவர்கள் அபூ ஸயீத் (ரழி) வாயிலாகப் பதிவு செய்துள்ள ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا لَا يَمُوتُونَ وَلَا يَحْيَوْنَ، وَأَمَّا أُنَاسٌ يُرِيدُ اللهُ بِهِمُ الرَّحْمَةَ فَيُمِيتُهُمْ فِي النَّارِ فَيَدْخُلُ عَلَيْهِمُ الشُّفَعَاءُ فَيَأْخُذُ الرَّجُلُ الضِّبَارَةَ فَيُنْبِتُهُمْ أو قال: يَنْبُتُونَ فِي نَهْرِ الْحَيَا، أو قال: الْحَيَاةِ، أو قال: الْحَيَوَانِ أو قال: نَهْرِ الْجَنَّةِ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ فِي حَمِيلِ السَّيْلِ»\n\r\n(\"நரகத்திற்குத் தகுதியான நரகவாசிகளைப் பொறுத்தவரை, அவர்கள் அங்கு சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். ஆனால் அல்லாஹ் யாருக்குக் கருணை காட்ட நாடுகிறானோ, அவர்களை நரக நெருப்பில் மரணிக்கச் செய்வான். பின்னர் பரிந்துரையாளர்கள் (ஷஃபாஅத் செய்ய) அனுமதிக்கப்படுவார்கள். ஒரு மனிதர் தனது குழுவினரை அழைத்துச் சென்று அல்-ஹயா (அல்லது அல்-ஹயாத் அல்லது அல்-ஹயவான் அல்லது சுவர்க்கத்தின் ஆறு) என்று அழைக்கப்படும் நதியில் அவர்களை நடுவார் (அல்லது அவர்கள் அங்கு முளைப்பார்கள்). ஓடும் நீரோடையின் ஓரத்தில் உள்ள வண்டல் மண்ணில் ஒரு விதை முளைப்பதைப் போல அவர்கள் மீண்டும் உயிர் பெற்று முளைப்பார்கள்.\") பின்னர் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«أَمَا تَرَوْنَ الشَّجَرَةَ تَكُونُ خَضْرَاءَ، ثُمَّ تَكُونُ صَفْرَاءَ، ثُمَّ تَكُونُ خَضْرَاءَ؟»\n\r\n(\"மரம் பச்சையாக இருந்து, பின்னர் மஞ்சளாக மாறி, மீண்டும் பச்சையாவதை நீங்கள் பார்த்ததில்லையா?\") அப்போது அங்கிருந்தவர்களில் சிலர், \"நபி (ஸல்) அவர்கள் பாலைவனவாசியைப் போல (இயற்கை உதாரணங்களைக் கூறி) பேசுகிறார்கள்\" என்று கூறினார்கள். இமாம் அஹ்மத் அவர்கள் அபூ ஸயீத் (ரழி) வாயிலாக மற்றுமொரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n«أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ، وَلَكِنْ أُنَاسٌ أو كما قال تُصِيبُهُمُ النَّارُ بِذُنُوبِهِمْ أو قال: بِخَطَايَاهُمْ فَيُمِيتُهُمْ إِمَاتَةً حَتَّى إِذَا صَارُوا فَحْمًا أُذِنَ فِي الشَّفَاعَةِ، فَجِيءَ بِهِمْ ضَبَائِرَ ضَبَائِرَ فَبُثُّوا عَلَى أَنْهَارِ الْجَنَّةِ فَيُقَالُ: يَا أَهْلَ الْجَنَّةِ أَفِيضُوا عَلَيْهِمْ، فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي حَمِيلِ السَّيْلِ»\n\r\n(\"நரகத்தில் நிரந்தரமாகத் தங்கும் நரகவாசிகள் அங்கு சாகவும் மாட்டார்கள், வாழவும் மாட்டார்கள். ஆனால், ஒரு கூட்டத்தினர் தங்களது பாவங்களின் காரணமாக நரக நெருப்பால் தண்டிக்கப்பட்டு, கரிக்கட்டையாக மாறும் வரை மரணிக்கச் செய்யப்படுவார்கள். பின்னர் அவர்களுக்குப் பரிந்துரை செய்ய அனுமதி வழங்கப்படும்; அவர்கள் குழு குழுவாகக் கொண்டு வரப்பட்டு சுவர்க்கத்தின் ஆறுகளில் விடப்படுவார்கள். அப்போது, 'சுவர்க்கவாசிகளே! இவர்கள் மீது தண்ணீரை ஊற்றுங்கள்' என்று கூறப்படும். வெள்ளத்தின் ஓரத்தில் உள்ள வண்டல் மண்ணில் விதை முளைப்பதைப் போல அவர்கள் மீண்டும் உயிர் பெறுவார்கள்.\") அப்போது அங்கிருந்தவர்களில் ஒருவர், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பாலைவனப் பகுதியில் வாழ்ந்தவரைப் போலவே (உவமைகளைக் கூறிப்) பேசுகிறார்கள்\" என்றார். இந்த ஹதீஸை முஸ்லிமும் பதிவு செய்துள்ளார்.\n\r\n\n\r\nதொழுகையும், தூய்மைப்படுத்துதலும்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nقَدْ أَفْلَحَ مَنْ تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى\n\r\n(நிச்சயமாக எவர் தூய்மை அடைந்து, தனது இறைவனின் பெயரை நினைவுகூர்ந்து தொழுதாரோ அவர் வெற்றி பெற்றுவிட்டார்.) அதாவது, எவர் தனது ஆத்மாவைத் தூய்மைப்படுத்தி, அருவருக்கத்தக்க பண்புகளை விட்டும் அதனைச் சுத்தப்படுத்தினாரோ, பின்னர் தனக்குக் கடமையாக்கப்பட்ட நேரத்தில் தொழுகையை நிறைவேற்றினாரோ அவர் வெற்றி பெற்றுவிட்டார். உமர் இப்னு அப்துல் அஸீஸ் (ரஹ்) அவர்கள், மக்கள் நோன்புப் பெருநாள் தொழுகைக்குச் செல்லும் போது இந்த வசனத்தை ஓதுமாறும், ஸதக்கத்துல் ஃபித்ர் (நோன்புப் பெருநாள் தர்மம்) வழங்குமாறும் கட்டளையிடுவார்கள்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nبَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا - وَالْآخِرَةُ خَيْرٌ وَأَبْقَى\n\r\n(எனினும், நீங்கள் உலக வாழ்க்கையையே தேர்ந்தெடுக்கிறீர்கள். ஆனால் மறுமையோ சிறந்ததும் நிலையானதும் ஆகும்.) அதாவது, நீங்கள் உலகத்தின் மீதுள்ள அன்பினால், மறுமையை விட உலகத்திற்கே முன்னுரிமை அளிக்கிறீர்கள். ஆனால் உலகத்தை விட மறுமையே சிறந்தது; அதுவே நிலையானது. இமாம் அஹ்மத் அவர்கள் அபூ மூஸா அல்-அஷ்அரீ (ரழி) வாயிலாகப் பதிவு செய்துள்ளதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: \"யார் தனது உலகத்தை நேசிக்கிறாரோ அவர் தனது மறுமைக்குப் பாதிப்பை ஏற்படுத்துகிறார். யார் தனது மறுமையை நேசிக்கிறாரோ அவர் தனது உலகத்திற்குப் பாதிப்பை ஏற்படுத்துகிறார். எனவே, அழிந்து போவதை விட நிலைத்திருப்பதற்கே முன்னுரிமை கொடுங்கள்.\"\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\nإِنَّ هَذَا لَفِي الصُّحُفِ الْأُولَى - صُحُفِ إِبْرَاهِيمَ وَمُوسَى\n\r\n(நிச்சயமாக இது முந்தைய வேதங்களிலும் உள்ளது; (அதாவது) இப்ராஹீம், மூஸா ஆகியோரின் ஏடுகளிலும் உள்ளது.) அதாவது, முந்தைய வசனங்களில் கூறப்பட்ட நற்போதனைகள், இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) ஆகியோரின் ஏடுகளிலும் உறுதிப்படுத்தப்பட்டுள்ளன. அபூதர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"நான், 'அல்லாஹ்வின் தூதரே! இப்ராஹீம் (அலை) அவர்களின் ஏடுகளில் என்ன இருந்தது?' என்று கேட்டேன். அதற்கு நபி (ஸல்) அவர்கள், 'அவை அனைத்தும் முன்னுதாரணங்களாக இருந்தன' என்று கூறிவிட்டுச் சிலவற்றை விவரித்தார்கள்: \"ஆதிக்கமும் சோதனையும் வழங்கப்பட்ட மன்னரே! உலகைச் சேகரிப்பதற்காக நான் உம்மை அனுப்பவில்லை. மாறாக, அநீதி இழைக்கப்பட்டவனின் பிரார்த்தனைக்கும் எனக்குமிடையே தடையை ஏற்படுத்துவதைத் தடுப்பதற்காகவே உம்மை அனுப்பினேன்; (அநீதி இழைக்கப்பட்டவன்) காஃபிராக இருந்தாலும் அவனது பிரார்த்தனையை நான் தட்டமாட்டேன்.\" பிறகு நான், 'மூஸா (அலை) அவர்களின் ஏடுகளில் என்ன இருந்தது?' என்று கேட்டேன். அதற்கு அவர்கள், 'அவை அனைத்தும் படிப்பினைகளாக இருந்தன' என்று கூறினார்கள்: \"மரணத்தை உறுதியாக அறிந்திருந்தும் மகிழ்ச்சியாக இருப்பவனைப் பற்றி நான் வியப்படைகிறேன்; நரகத்தை உறுதியாக அறிந்திருந்தும் சிரிப்பவனைப் பற்றி நான் வியப்படைகிறேன்; உலகத்தையும் அது தனது உரிமையாளர்களை மாற்றிக்கொண்டே இருப்பதையும் கண்டும், அதில் அமைதி காண்பவனைப் பற்றி நான் வியப்படைகிறேன்; விதியை நம்பியும் (இழப்பைக் கண்டு) சோகத்தில் ஆழ்ந்துவிடுபவனைப் பற்றி நான் வியப்படைகிறேன்; மறுமை விசாரணையை நம்பியும் அமல் செய்யாமல் இருப்பவனைப் பற்றி நான் வியப்படைகிறேன்.\"\" (நஸயீ)\n\r\n(தப்ஸீர் இப்னு கஸீர் சுருக்கம் முற்றிற்று.)"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=19\" class=\"link\">87:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:19 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=19\" class=\"link\">87:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:19 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=19\" class=\"link\">87:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:19 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=19\" class=\"link\">87:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:19 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=87&ayah=19\" class=\"link\">87:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 87:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>வெற்றி பெற்றவர்களைப் பற்றிய ஒரு விளக்கம்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span><br />\r\n<br />\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார்.) அதாவது, அவர் இழிவான குணங்களிலிருந்து தன்னைத் தூய்மைப்படுத்திக் கொண்டு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு அல்லாஹ் அருளிய வஹீ (இறைச்செய்தி)யைப் பின்பற்றுகிறார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span><br />\r\n<br />\r\n(மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.) அதாவது, அவர் அல்லாஹ்வின் திருப்தியை நாடியும், அவனது கட்டளைக்குக் கீழ்ப்படிந்தும், அவனது சட்டத்தை நடைமுறைப்படுத்தியும், உரிய நேரத்தில் தொழுகையை நிலைநாட்டுகிறார். முஃமின்களின் தலைவர் உமர் பின் அப்துல் அஸீஸ் அவர்கள், மக்களுக்கு ஸதக்கத்துல் ஃபித்ர் கொடுக்கும்படி கட்டளையிடுபவர்களாக இருந்தார்கள் என்றும், அப்போது இந்த வசனத்தை ஓதுவார்கள் என்றும் நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span><br />\r\n<br />\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.) அபூ அல்-அஹ்வஸ் அவர்கள் கூறினார்கள், \"உங்களில் யாரிடமாவது ஒருவர் யாசகம் கேட்டு வந்து, அந்த நேரத்தில் அவர் தொழ விரும்பினால், அவர் தொழுவதற்கு முன்னதாக தர்மம் (ஸகாத்) வழங்கட்டும். ஏனெனில், நிச்சயமாக உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span><br />\r\n<br />\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.)\" கதாதா அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறுகையில்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span><br />\r\n<br />\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார் (ஃபஸல்லா).) \"அவர் தனது செல்வத்தைத் தூய்மைப்படுத்தி, தனது படைப்பாளனைத் திருப்திப்படுத்துகிறார்\" என்று விளக்கமளித்தார்கள்.<br />\r\n<br />\r\n<strong>மறுமையுடன் ஒப்பிடும்போது இவ்வுலகம் மதிப்பற்றது</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">تُؤْثِرُونَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(மாறாக, நீங்கள் இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறீர்கள்.) அதாவது, 'மறுமையின் விவகாரத்தை விட இவ்வுலகிற்கே நீங்கள் முன்னுரிமை வழங்குகிறீர்கள். இவ்வுலக வாழ்வாதாரத்தில் உங்களுக்குக் கிடைக்கும் பயன்கள், லாபங்கள் மற்றும் ஆதாயங்களின் காரணமாக நீங்கள் இதையே விரும்புகிறீர்கள்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى</span><br />\r\n<br />\r\n(மறுமையோ சிறந்ததும், நிலைத்திருக்கக் கூடியதுமாகும்.) அதாவது, மறுமை இல்லத்தின் பிரதிபலன் இவ்வுலக வாழ்க்கையை விடச் சிறந்தது, மேலும் அது என்றென்றும் நிலைத்திருக்கக் கூடியது. நிச்சயமாக இவ்வுலக வாழ்க்கை தாழ்வானது மற்றும் தற்காலிகமானது; ஆனால் மறுமையோ கண்ணியமானது மற்றும் நிலையானது. அவ்வாறிருக்க, ஒரு புத்திசாலி எப்படி நிலையானதை விட தற்காலிகமானதைத் தேர்ந்தெடுக்க முடியும்? விரைவில் அழியக்கூடிய ஒன்றுக்கு அவர் எப்படி முக்கியத்துவம் கொடுத்துவிட்டு, முடிவில்லாத நிலையான வசிப்பிடத்தைப் புறக்கணிக்க முடியும்? இமாம் அஹ்மத் அவர்கள் அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் வழியாக அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">دُنْيَاهُ</span> <span class=\"quran-arabic-font text-success\">أَضَرَّ</span> <span class=\"quran-arabic-font text-success\">بِآخِرَتِهِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَحَبَّ</span> <span class=\"quran-arabic-font text-success\">آخِرَتَهُ</span> <span class=\"quran-arabic-font text-success\">أَضَرَّ</span> <span class=\"quran-arabic-font text-success\">بِدُنْيَاهُ،</span> <span class=\"quran-arabic-font text-success\">فَآثِرُوا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَبْقَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَفْنَى</span>»<br />\r\n<br />\r\n(யார் தனது இவ்வுலக வாழ்க்கையை நேசிக்கிறாரோ, அவர் தனது மறுமைக்குத் தீங்கு இழைக்கிறார். யார் தனது மறுமையை நேசிக்கிறாரோ, அவர் தனது இவ்வுலக வாழ்க்கைக்குத் தீங்கு இழைக்கிறார். எனவே, அழியக்கூடியதை விட நிலையானதையே தேர்ந்தெடுங்கள்.) அஹ்மத் அவர்கள் மட்டுமே இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\n<strong>இப்ராஹீம் மற்றும் மூஸாவின் வேதங்கள்</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">الصُّحُفِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> - <span class=\"quran-arabic-font text-success\">صُحُفِ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">وَمُوسَى</span><br />\r\n<br />\r\n(நிச்சயமாக, இது முந்தைய வேதங்களில் உள்ளது -- இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) அவர்களின் வேதங்களில்.) இந்த வசனம் ஸூரத்துந் நஜ்மில் அல்லாஹ் கூறும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُنَبَّأْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صُحُفِ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> - <span class=\"quran-arabic-font text-success\">وَإِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">وَفَّى</span> - <span class=\"quran-arabic-font text-success\">أَلَّا</span> <span class=\"quran-arabic-font text-success\">تَزِرُ</span> <span class=\"quran-arabic-font text-success\">وَازِرَةٌ</span> <span class=\"quran-arabic-font text-success\">وِزْرَ</span> <span class=\"quran-arabic-font text-success\">أُخْرَى</span> - <span class=\"quran-arabic-font text-success\">وَأَن</span> <span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">لِلْإِنسَانِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">سَعَى</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">سَعْيَهُ</span> <span class=\"quran-arabic-font text-success\">سَوْفَ</span> <span class=\"quran-arabic-font text-success\">يُرَى</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُجْزَاهُ</span> <span class=\"quran-arabic-font text-success\">الْجَزَاءَ</span> <span class=\"quran-arabic-font text-success\">الْأَوْفَى</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْمُنتَهَى</span><br />\r\n<br />\r\n(அல்லது மூஸா (அலை) அவர்களின் வேதங்களில் உள்ளதைப் பற்றி அவருக்கு அறிவிக்கப்படவில்லையா? மேலும் (அல்லாஹ் கட்டளையிட்டவற்றை) முழுமையாக நிறைவேற்றிய இப்ராஹீம் (அலை) அவர்களின் வேதங்களிலும் உள்ளதை: அதாவது, ஒருவருடைய பாவச் சுமையை மற்றொருவர் சுமக்க மாட்டார். மேலும், மனிதனுக்கு அவன் முயற்சி செய்ததைத் தவிர வேறெதுவும் இல்லை. அவனது முயற்சி விரைவில் காண்பிக்கப்படும். பின்னர் அவனுக்குப் பூரணமான கூலி வழங்கப்படும். நிச்சயமாக உம் இறைவனிடமே (அனைத்து காரியங்களின்) இறுதி முடிவு இருக்கிறது.) (<a href=\"qurandisp.php?sura=53&ayah=36\" class=\"link\">53:36</a>-42). அந்த வசனங்களின் இறுதி வரை இது போன்ற கருத்துக்கள் கூறப்பட்டுள்ளன. அபூ ஆலியா அவர்கள் கூறுகையில், \"இந்த ஸூராவின் செய்திகள் முந்தைய வேதங்களில் இடம்பெற்றுள்ளன\" என்றார்கள். இப்னு ஜரீர் அவர்கள் பின்வரும் கருத்தையே சிறந்ததாகக் கருதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَآ</span><br />\r\n<br />\r\n(நிச்சயமாக, இது) என்பது அல்லாஹ் முன்னதாகக் கூறிய இந்த வசனங்களைக் குறிக்கிறது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَزَكَّى</span> - <span class=\"quran-arabic-font text-success\">وَذَكَرَ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">فَصَلَّى</span> - <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">تُؤْثِرُونَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَاةَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> - <span class=\"quran-arabic-font text-success\">وَالْآخِرَةُ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">وَأَبْقَى</span><br />\r\n<br />\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார். மாறாக, நீங்கள் இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறீர்கள். மறுமையோ சிறந்ததும், நிலைத்திருக்கக் கூடியதுமாகும்.) பிறகு அல்லாஹ் கூறுகிறான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَآ</span><br />\r\n<br />\r\n(நிச்சயமாக, இது) அதாவது, இந்த விவாதத்தின் உள்ளடக்கமானது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">الصُّحُفِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> - <span class=\"quran-arabic-font text-success\">صُحُفِ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">وَمُوسَى</span><br />\r\n<br />\r\n(முந்தைய வேதங்களில், இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) அவர்களின் வேதங்களில் உள்ளது.) அவர் (அத்-தபரீ) தேர்ந்தெடுத்த இந்தக் கருத்து மிகவும் பொருத்தமானதாகவும் வலிமையானதாகவும் உள்ளது. இதைப் போன்றே கதாதா மற்றும் இப்னு ஸைத் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் ஸூரத்துல் அஃலா (ஸப்பிஹ்) வின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது. அவனே வெற்றியைத் தருபவனும், தவறுகளிலிருந்து பாதுகாப்பவனுமாவான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"வெற்றி பெற்றவர்களைப் பற்றிய ஒரு விளக்கம்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nقَدْ أَفْلَحَ مَن تَزَكَّى\n\r\n\n\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார்.) அதாவது, அவர் இழிவான குணங்களிலிருந்து தன்னைத் தூய்மைப்படுத்திக் கொண்டு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு அல்லாஹ் அருளிய வஹீ (இறைச்செய்தி)யைப் பின்பற்றுகிறார்.\n\r\n\n\r\nوَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى\n\r\n\n\r\n(மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.) அதாவது, அவர் அல்லாஹ்வின் திருப்தியை நாடியும், அவனது கட்டளைக்குக் கீழ்ப்படிந்தும், அவனது சட்டத்தை நடைமுறைப்படுத்தியும், உரிய நேரத்தில் தொழுகையை நிலைநாட்டுகிறார். முஃமின்களின் தலைவர் உமர் பின் அப்துல் அஸீஸ் அவர்கள், மக்களுக்கு ஸதக்கத்துல் ஃபித்ர் கொடுக்கும்படி கட்டளையிடுபவர்களாக இருந்தார்கள் என்றும், அப்போது இந்த வசனத்தை ஓதுவார்கள் என்றும் நாம் ஏற்கனவே குறிப்பிட்டுள்ளோம்:\n\r\n\n\r\nقَدْ أَفْلَحَ مَن تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى\n\r\n\n\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.) அபூ அல்-அஹ்வஸ் அவர்கள் கூறினார்கள், \"உங்களில் யாரிடமாவது ஒருவர் யாசகம் கேட்டு வந்து, அந்த நேரத்தில் அவர் தொழ விரும்பினால், அவர் தொழுவதற்கு முன்னதாக தர்மம் (ஸகாத்) வழங்கட்டும். ஏனெனில், நிச்சயமாக உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقَدْ أَفْلَحَ مَن تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى\n\r\n\n\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார்.)\" கதாதா அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறுகையில்,\n\r\n\n\r\nقَدْ أَفْلَحَ مَن تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى\n\r\n\n\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார் (ஃபஸல்லா).) \"அவர் தனது செல்வத்தைத் தூய்மைப்படுத்தி, தனது படைப்பாளனைத் திருப்திப்படுத்துகிறார்\" என்று விளக்கமளித்தார்கள்.\n\r\n\n\r\nமறுமையுடன் ஒப்பிடும்போது இவ்வுலகம் மதிப்பற்றது\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nبَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا\n\r\n\n\r\n(மாறாக, நீங்கள் இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறீர்கள்.) அதாவது, 'மறுமையின் விவகாரத்தை விட இவ்வுலகிற்கே நீங்கள் முன்னுரிமை வழங்குகிறீர்கள். இவ்வுலக வாழ்வாதாரத்தில் உங்களுக்குக் கிடைக்கும் பயன்கள், லாபங்கள் மற்றும் ஆதாயங்களின் காரணமாக நீங்கள் இதையே விரும்புகிறீர்கள்.'\n\r\n\n\r\nوَالْآخِرَةُ خَيْرٌ وَأَبْقَى\n\r\n\n\r\n(மறுமையோ சிறந்ததும், நிலைத்திருக்கக் கூடியதுமாகும்.) அதாவது, மறுமை இல்லத்தின் பிரதிபலன் இவ்வுலக வாழ்க்கையை விடச் சிறந்தது, மேலும் அது என்றென்றும் நிலைத்திருக்கக் கூடியது. நிச்சயமாக இவ்வுலக வாழ்க்கை தாழ்வானது மற்றும் தற்காலிகமானது; ஆனால் மறுமையோ கண்ணியமானது மற்றும் நிலையானது. அவ்வாறிருக்க, ஒரு புத்திசாலி எப்படி நிலையானதை விட தற்காலிகமானதைத் தேர்ந்தெடுக்க முடியும்? விரைவில் அழியக்கூடிய ஒன்றுக்கு அவர் எப்படி முக்கியத்துவம் கொடுத்துவிட்டு, முடிவில்லாத நிலையான வசிப்பிடத்தைப் புறக்கணிக்க முடியும்? இமாம் அஹ்மத் அவர்கள் அபூ மூஸா அல்-அஷ்அரீ (ரழி) அவர்கள் வழியாக அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنْ أَحَبَّ دُنْيَاهُ أَضَرَّ بِآخِرَتِهِ، وَمَنْ أَحَبَّ آخِرَتَهُ أَضَرَّ بِدُنْيَاهُ، فَآثِرُوا مَا يَبْقَى عَلَى مَا يَفْنَى»\n\r\n\n\r\n(யார் தனது இவ்வுலக வாழ்க்கையை நேசிக்கிறாரோ, அவர் தனது மறுமைக்குத் தீங்கு இழைக்கிறார். யார் தனது மறுமையை நேசிக்கிறாரோ, அவர் தனது இவ்வுலக வாழ்க்கைக்குத் தீங்கு இழைக்கிறார். எனவே, அழியக்கூடியதை விட நிலையானதையே தேர்ந்தெடுங்கள்.) அஹ்மத் அவர்கள் மட்டுமே இந்த ஹதீஸைப் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\nஇப்ராஹீம் மற்றும் மூஸாவின் வேதங்கள்\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nإِنَّ هَذَا لَفِي الصُّحُفِ الْأُولَى - صُحُفِ إِبْرَاهِيمَ وَمُوسَى\n\r\n\n\r\n(நிச்சயமாக, இது முந்தைய வேதங்களில் உள்ளது -- இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) அவர்களின் வேதங்களில்.) இந்த வசனம் ஸூரத்துந் நஜ்மில் அல்லாஹ் கூறும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nأَمْ لَمْ يُنَبَّأْ بِمَا فِي صُحُفِ مُوسَى - وَإِبْرَاهِيمَ الَّذِي وَفَّى - أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى - وَأَن لَّيْسَ لِلْإِنسَانِ إِلَّا مَا سَعَى - وَأَنَّ سَعْيَهُ سَوْفَ يُرَى - ثُمَّ يُجْزَاهُ الْجَزَاءَ الْأَوْفَى - وَأَنَّ إِلَى رَبِّكَ الْمُنتَهَى\n\r\n\n\r\n(அல்லது மூஸா (அலை) அவர்களின் வேதங்களில் உள்ளதைப் பற்றி அவருக்கு அறிவிக்கப்படவில்லையா? மேலும் (அல்லாஹ் கட்டளையிட்டவற்றை) முழுமையாக நிறைவேற்றிய இப்ராஹீம் (அலை) அவர்களின் வேதங்களிலும் உள்ளதை: அதாவது, ஒருவருடைய பாவச் சுமையை மற்றொருவர் சுமக்க மாட்டார். மேலும், மனிதனுக்கு அவன் முயற்சி செய்ததைத் தவிர வேறெதுவும் இல்லை. அவனது முயற்சி விரைவில் காண்பிக்கப்படும். பின்னர் அவனுக்குப் பூரணமான கூலி வழங்கப்படும். நிச்சயமாக உம் இறைவனிடமே (அனைத்து காரியங்களின்) இறுதி முடிவு இருக்கிறது.) (53:36-42). அந்த வசனங்களின் இறுதி வரை இது போன்ற கருத்துக்கள் கூறப்பட்டுள்ளன. அபூ ஆலியா அவர்கள் கூறுகையில், \"இந்த ஸூராவின் செய்திகள் முந்தைய வேதங்களில் இடம்பெற்றுள்ளன\" என்றார்கள். இப்னு ஜரீர் அவர்கள் பின்வரும் கருத்தையே சிறந்ததாகக் கருதினார்கள்:\n\r\n\n\r\nإِنَّ هَذَآ\n\r\n\n\r\n(நிச்சயமாக, இது) என்பது அல்லாஹ் முன்னதாகக் கூறிய இந்த வசனங்களைக் குறிக்கிறது:\n\r\n\n\r\nقَدْ أَفْلَحَ مَن تَزَكَّى - وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّى - بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا - وَالْآخِرَةُ خَيْرٌ وَأَبْقَى\n\r\n\n\r\n(நிச்சயமாக எவர் தன்னைத் தூய்மைப்படுத்திக் கொண்டாரோ அவர் வெற்றி பெற்றுவிட்டார். மேலும், அவர் தன் இறைவனின் பெயரை நினைவு கூர்ந்து, தொழுகையை நிறைவேற்றுகிறார். மாறாக, நீங்கள் இவ்வுலக வாழ்க்கைக்கு முன்னுரிமை அளிக்கிறீர்கள். மறுமையோ சிறந்ததும், நிலைத்திருக்கக் கூடியதுமாகும்.) பிறகு அல்லாஹ் கூறுகிறான்,\n\r\n\n\r\nإِنَّ هَذَآ\n\r\n\n\r\n(நிச்சயமாக, இது) அதாவது, இந்த விவாதத்தின் உள்ளடக்கமானது,\n\r\n\n\r\nإِنَّ هَذَا لَفِي الصُّحُفِ الْأُولَى - صُحُفِ إِبْرَاهِيمَ وَمُوسَى\n\r\n\n\r\n(முந்தைய வேதங்களில், இப்ராஹீம் (அலை) மற்றும் மூஸா (அலை) அவர்களின் வேதங்களில் உள்ளது.) அவர் (அத்-தபரீ) தேர்ந்தெடுத்த இந்தக் கருத்து மிகவும் பொருத்தமானதாகவும் வலிமையானதாகவும் உள்ளது. இதைப் போன்றே கதாதா மற்றும் இப்னு ஸைத் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அல்லாஹ்வே மிக அறிந்தவன். இத்துடன் ஸூரத்துல் அஃலா (ஸப்பிஹ்) வின் தஃப்சீர் நிறைவுற்றது. எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே உரியது. அவனே வெற்றியைத் தருபவனும், தவறுகளிலிருந்து பாதுகாப்பவனுமாவான்."}}};})(self);
